package connect

// ResultOf determines the winner of a game of Hex / Polygon.
//
// The board is given as a list of lines in the usual parallelogram
// representation: line i holds the cells of row i, with each row
// indented by one extra space for readability (the spaces carry no
// meaning and may be omitted).
//
// Player "O" connects the top side to the bottom side; player "X"
// connects the left side to the right side. The result is the name of
// the player who has a chain of stones between their two sides, or
// "" if nobody has won.
func ResultOf(lines []string) (string, error) {
	size := len(lines)
	if size == 0 {
		return "", nil
	}

	grid := make([][]byte, size)
	for i, line := range lines {
		grid[i] = []byte(line)
	}

	if connects(grid, 'O') {
		return "O", nil
	}
	if connects(grid, 'X') {
		return "X", nil
	}
	return "", nil
}

// connects reports whether the given player has a chain of stones from
// their start side to the opposite side. "O" plays from top to bottom,
// "X" from left to right.
func connects(grid [][]byte, player byte) bool {
	size := len(grid)
	vertical := player == 'O'

	onStart := func(r, c int) bool {
		if vertical {
			return r == 0
		}
		return c == 0
	}
	onFinish := func(r, c int) bool {
		if vertical {
			return r == size-1
		}
		return c == len(grid[r])-1
	}

	// The six neighbours of a cell in the parallelogram layout: each
	// row is shifted half a cell to the right relative to the one
	// above it.
	neighbours := [6][2]int{
		{-1, 0}, {-1, 1},
		{0, -1}, {0, 1},
		{1, -1}, {1, 0},
	}

	visited := make([][]bool, size)
	var stack [][2]int
	for r := range grid {
		visited[r] = make([]bool, len(grid[r]))
		for c := range grid[r] {
			if grid[r][c] == player && onStart(r, c) {
				visited[r][c] = true
				stack = append(stack, [2]int{r, c})
			}
		}
	}

	for len(stack) > 0 {
		pos := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		r, c := pos[0], pos[1]

		if onFinish(r, c) {
			return true
		}

		for _, d := range neighbours {
			nr, nc := r+d[0], c+d[1]
			if nr < 0 || nr >= size || nc < 0 || nc >= len(grid[nr]) {
				continue
			}
			if grid[nr][nc] != player || visited[nr][nc] {
				continue
			}
			visited[nr][nc] = true
			stack = append(stack, [2]int{nr, nc})
		}
	}

	return false
}

